import{_ as a,H as t,f as o,i as n}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"plan","description":"","frontmatter":{},"headers":[],"relativePath":"skills/plan.md","filePath":"en/skills/plan.md"}'),s={name:"skills/plan.md"};function l(c,e,d,i,r,p){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="plan" tabindex="-1">plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;plan&quot;">​</a></h1><p>The <code>plan</code> skill breaks an approved specification into executable milestone tasks in <code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code>. It references the spec rather than restating background, architecture, or rationale.</p><h2 id="rolling-wave-multi-module-scope" tabindex="-1">Rolling Wave &amp; Multi-Module Scope <a class="header-anchor" href="#rolling-wave-multi-module-scope" aria-label="Permalink to &quot;Rolling Wave &amp; Multi-Module Scope&quot;">​</a></h2><ul><li><strong>Rolling wave</strong>: When a spec references <code>milestone: MN</code> in <code>docs/ROADMAP.md</code>, expand only that milestone and leave later milestones as one-line stubs. After <code>ship</code>, confirm the next milestone before expanding it; return to <code>design</code> only if its goal materially changed.</li><li><strong>Multi-module topology</strong>: If <code>topology=multi-module</code> is declared, read <a href="./multi-module.html">Multi-Module Protocol</a> and open the coordinator workspace plan with the declaration block (<code>topology: multi-module</code>, <code>change-set</code>, <code>coordinator</code>, <code>repos</code>, module plan paths, and integration task). Every task names one <code>repository:</code> and one <code>module:</code>, ordered contracts → consumers → local acceptance → integration → linked commits.</li></ul><h2 id="milestone-tasks-30–60-min-each" tabindex="-1">Milestone Tasks (30–60 min each) <a class="header-anchor" href="#milestone-tasks-30–60-min-each" aria-label="Permalink to &quot;Milestone Tasks (30–60 min each)&quot;">​</a></h2><p>Each task is written as a checkbox (<code>- [ ] T&lt;n&gt;: &lt;name&gt;</code>) — never a heading — with concrete metadata:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>goal:       &lt;one sentence&gt;</span></span>
<span class="line"><span>files:      &lt;paths&gt;</span></span>
<span class="line"><span>acceptance: &lt;executable test, command, or explicit manual check&gt;</span></span>
<span class="line"><span>spec:       &lt;docs/staging/specs/...#anchor&gt;</span></span></code></pre></div><p>Independent tasks with closed contracts and disjoint write scopes are marked <code>[parallel] T3, T4, T5</code>. Atomic step-by-step expansion is deferred to dispatch time (<code>subagents</code>).</p><h2 id="hand-off-gate" tabindex="-1">Hand-Off Gate <a class="header-anchor" href="#hand-off-gate" aria-label="Permalink to &quot;Hand-Off Gate&quot;">​</a></h2><p><code>&lt;gate&gt;</code><code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code> (and every module plan for multi-module work) must exist on disk and be confirmed by the user before handing off to <code>tdd</code> or <code>subagents</code>. <code>&lt;/gate&gt;</code></p>`,10)])])}const u=a(s,[["render",l]]);export{h as __pageData,u as default};
